#define BUBBLE_COLOR (vec3(255.0, 255.0, 255.0) / 255.0)
#define BACKGROUND_COLOR (vec3(46.0, 37.0, 47.0) / 255.0)
#define BUBBLE_THICKNESS 0.02
#define SUBBUBBLE_COUNT 3

#define EXPLODE_OFFSET (MERGING_DURATION + FLAT_DURATION + BREAK_DURATION * 0.618)
#define FULL_LOOP_DURATION (MERGING_DURATION + FLAT_DURATION + BREAK_DURATION + EXTRA_DURATION)
#define MERGING_DURATION 1.6
#define FLAT_DURATION 0.8
#define BREAK_DURATION 0.8
#define EXTRA_DURATION 0.2

// 泡泡的形状是通过有向距离场描述的
// https://en.wikipedia.org/wiki/Signed_distance_function
// 有向距离场函数描述空间任意一点到图形表面的距离，这方便做形状的混合

// Inigo Quilez写了很多关于SDF的文章
// 这里相关的有:
// 基础二维图形的SDF： https://iquilezles.org/articles/distfunctions2d/
// SDF的平滑混合和相减： https://iquilezles.org/articles/distfunctions/

// 主角站在平台上会让泡泡顶部变平，是因为减去了这一部分SDF描述的形状
float GetClipPlaneSDF(vec2 samplePos, vec2 sdfPos, vec2 sdfNormal)
{
    return dot(samplePos - sdfPos, sdfNormal);
}

// 单个泡泡的SDF
float GetBubbleSDF(vec2 samplePos, vec2 sdfPos, float radius)
{
    samplePos = samplePos - sdfPos;
    float sdf = length(samplePos) - radius;

    // 通过极坐标采样二维柏林噪声，偏移泡泡表面的距离，并且拿时间作为一个采样维度
    // 这样就能得到泡泡表面的扭曲动画
    float polar = atan(samplePos.y, samplePos.x) / PI * 0.5 + 0.5;
    float noise = perlin(vec2(polar, iTime * 0.1), vec2(8.0, 8.0), vec2(1.0, 65535.0), vec2(lgc(), lgc()));
    sdf += noise * 0.12 * radius;

    return sdf;
}

struct BubbleInfo
{
    vec2 pos;
    float radius;
    float blend;
};

float GetSDF(vec2 uv)
{
    float time = mod((iTime + EXPLODE_OFFSET), FULL_LOOP_DURATION);
    float mergingProgress = smoothstep(0.0, 1.0, time / MERGING_DURATION);

    // 我在通过MeshRenderer渲染一个Quad的时候把一组球体的半径和位置信息通过MaterialPropertyBlock传给着色器那边
    // 然后算这些元素对应的SDF并且做混合
    // 这个传数据的办法不太聪明，因为是打Jam所以临时这么做
    // 正常可以考虑直接调InstanceDraw同时传入Per Instance的数据
    vec2 mainBubblePos = vec2(0.0, 0.0);
    float mainBubbleArea = mix(0.02, 0.04, lgc());
    float mainBubbleRadius = sqrt(mainBubbleArea);

    BubbleInfo[SUBBUBBLE_COUNT] bubbleInfos;

    for(int i = 0; i < SUBBUBBLE_COUNT; i++)
    {
        vec2 subBubblePos = normalize(vec2(lgc(), lgc()) * 2.0 - vec2(1.0));
        subBubblePos *= (1.0 - mergingProgress) * mix(0.4, 1.0, lgc());
        float subBubbleArea = mix(0.002, 0.006, lgc());
        float subBubbleRadius = sqrt(subBubbleArea);
        float subBubbleMergingProgress = 1.0 - clamp((distance(mainBubblePos, subBubblePos) - subBubbleRadius) / mainBubbleRadius, 0.0, 1.0);
        subBubbleRadius *= 1.0 - subBubbleMergingProgress;
        mainBubbleArea += mix(0.0, subBubbleArea, subBubbleMergingProgress);

        bubbleInfos[i] = BubbleInfo(subBubblePos, subBubbleRadius, subBubbleMergingProgress);
    }

    mainBubbleRadius = sqrt(mainBubbleArea);

    float breakProgress = 1.0 - clamp((time - MERGING_DURATION - FLAT_DURATION) / BREAK_DURATION, 0.0, 1.0);
    breakProgress = 1.0 - breakProgress * breakProgress;
    mainBubbleRadius *= mix(1.0, 1.618, breakProgress);

    float sdf = GetBubbleSDF(uv, mainBubblePos, mainBubbleRadius);
    for(int i = 0; i < SUBBUBBLE_COUNT; i++)
    {
        sdf = smin(sdf, GetBubbleSDF(uv, bubbleInfos[i].pos, bubbleInfos[i].radius), mix(0.0001, 0.3, bubbleInfos[i].blend));
    }

    // 削去了上方的部分
    float flatProgress = smoothstep(0.0, 1.0, (time - MERGING_DURATION) / FLAT_DURATION);
    float clippedSDF = ssub(sdf, GetClipPlaneSDF(uv, vec2(0.0, mainBubbleRadius / sqrt(2.0)), vec2(0.0, -1.0)), 0.1);
    sdf = mix(mix(sdf, clippedSDF, flatProgress), sdf, breakProgress);

    return sdf;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    uint loopCount = uint((iTime + EXPLODE_OFFSET) / FULL_LOOP_DURATION);
    lgcInit(murmurHash11(loopCount));

    vec2 uv = fragCoord / iResolution.y + vec2(iResolution.x / iResolution.y * -0.5, -0.5);
    float sdf = GetSDF(uv);

    float halfThickness = BUBBLE_THICKNESS / 2.0;
    float shapeFactor = 1.0 - abs(sdf + halfThickness) / halfThickness;

    // 采样细胞图噪声来做破碎时的消散效果
    float time = mod((iTime + EXPLODE_OFFSET), FULL_LOOP_DURATION);
    float breakProgress = clamp((time - MERGING_DURATION - FLAT_DURATION) / BREAK_DURATION, 0.0, 1.0);
    float breakNoise = (1.0 - voronoi(uv / mix(1.0, 1.618, 1.0 - (1.0 - breakProgress) * (1.0 - breakProgress)), vec2(16.0, 16.0), vec2(65535.0, 65535.0), vec2(lgc() * 256.0, lgc() * 256.0))) * smoothstep(0.1, 0.0, abs(sdf + halfThickness)) - breakProgress;

    // 通过fwidth做的抗锯齿
    // 如果没有混合breakNoise的结果，只是对SDF描述的图形做AA的话也可以直接用一个像素对应大小做smoothstep
    // 当然Jam的时候做的是像素艺术游戏所以不用考虑这个哈哈
    shapeFactor = mix(shapeFactor, breakNoise, smoothstep(0.0, 0.3, breakProgress));
    float aa = fwidth(shapeFactor);
    shapeFactor = smoothstep(0.0, aa, shapeFactor);

    vec3 outputColor = mix(BACKGROUND_COLOR, BUBBLE_COLOR, shapeFactor);

    // Output to screen
    fragColor = vec4(outputColor,1.0);
}

# define PI 3.1415926535897932384626433832795
# define INT_MAX 0xffffffffu

// SDF运算
float smin(float a, float b, float k)
{
    float h = max(k - abs(a - b), 0.0);
    return min(a, b) - h * h * 0.25 / k;
}

float ssub(float a, float b, float k)
{
    float h = clamp( 0.5 - 0.5 * (b + a) / k, 0.0, 1.0 );
    return mix(a, -b, h) + k * h * (1.0 - h);
}

// 哈希随机数生成
uint murmurHash11(uint src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

uvec2 murmurHash22(uvec2 src) {
    const uint M = 0x5bd1e995u;
    uvec2 h = uvec2(1190494759u, 2147483647u);
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

vec2 hash22(vec2 src) {
    uvec2 h = murmurHash22(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0;
}

// 线性同余随机数生成
uint lgcCurrent;
const uint lgcFactor = uint(22695477);
const uint lgcAdder = uint(1);

float lgc()
{
    lgcCurrent = (lgcCurrent * lgcFactor + lgcAdder) % INT_MAX;
    return uintBitsToFloat(lgcCurrent & 0x007fffffu | 0x3f800000u) - 1.0;
}

void lgcInit(uint seed)
{
    lgcCurrent = seed;
}

// 噪声
float perlin(vec2 p, vec2 freq, vec2 rep, vec2 offset)
{
    p += offset / freq;
    p *= freq;
    vec4 gridSet = floor(p.xyxy) + vec4(0.0, 0.0, 1.0, 1.0);
    vec4 dirSet = fract(p.xyxy) - vec4(0.0, 0.0, 1.0, 1.0);
    // 必要时保证噪声在连接处连续
    gridSet = mod(gridSet, (rep * freq).xyxy);

    vec2 gridLevel_00 = hash22(gridSet.xy) * 2.0 - 1.0;
    vec2 gridLevel_01 = hash22(gridSet.xw) * 2.0 - 1.0;
    vec2 gridLevel_10 = hash22(gridSet.zy) * 2.0 - 1.0;
    vec2 gridLevel_11 = hash22(gridSet.zw) * 2.0 - 1.0;

    float product_00 = dot(gridLevel_00, dirSet.xy);
    float product_01 = dot(gridLevel_01, dirSet.xw);
    float product_10 = dot(gridLevel_10, dirSet.zy);
    float product_11 = dot(gridLevel_11, dirSet.zw);

    float t_0 = pow(dirSet.x, 3.0) * (6.0 * pow(dirSet.x, 2.0) - 15.0 * dirSet.x + 10.0);
    float t_1 = pow(dirSet.y, 3.0) * (6.0 * pow(dirSet.y, 2.0) - 15.0 * dirSet.y + 10.0);

    // return dirSet.x;
    return mix(mix(product_00, product_10, t_0), mix(product_01, product_11, t_0), t_1);
}

float voronoi(vec2 p, vec2 freq, vec2 rep, vec2 offset) {
    p *= freq;
    p += offset;
    vec2 point = floor(p);
    vec2 f = fract(p);
    float res = 0.0;
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 b = vec2(i, j);
            vec2 pos = mod(point + b, rep * freq);
            vec2 r = vec2(b) - f + hash22(pos);
            res += 1.0 / pow(dot(r, r), 8.0);
        }
    }
    return pow(1.0 / res, 0.0625);
}
